package solidity

import "github.com/silasdev78/silas-code-inspector/internal/domain"

func Patterns() []domain.Pattern {
	return []domain.Pattern{
		{ID: "SOL-001", Title: "Missing Access Control", Regex: `function\s+\w+\s*\([^)]*\)\s*(?:public|external)\s*(?!.*onlyOwner|.*onlyRole|.*require\s*\(\s*msg\.sender)`, Severity: domain.SeverityCritical, Description: "Sensitive function lacks access control (onlyOwner/onlyRole/hasRole).", Recommendation: "Add OpenZeppelin AccessControl or Ownable modifier with timelock."},
		{ID: "SOL-002", Title: "tx.origin Authentication", Regex: `tx\.origin`, Severity: domain.SeverityHigh, Description: "tx.origin used for authentication, vulnerable to phishing attacks.", Recommendation: "Replace tx.origin with msg.sender."},
		{ID: "SOL-003", Title: "Unprotected selfdestruct", Regex: `selfdestruct\s*\(`, Severity: domain.SeverityCritical, Description: "selfdestruct without access control can destroy contract.", Recommendation: "Add require(msg.sender == owner) before selfdestruct."},
		{ID: "SOL-004", Title: "Uninitialized Proxy / Missing Initializer Protection", Regex: `function\s+initialize\s*\(`, Severity: domain.SeverityCritical, Description: "Initialize function may be called multiple times, hijacking proxy.", Recommendation: "Add initializer modifier and _disableInitializers()."},
		{ID: "SOL-005", Title: "Centralized Risk (Single EOA Owner)", Regex: `address\s+(?:public|private|internal)\s+owner\s*=`, Severity: domain.SeverityHigh, Description: "Single EOA owner poses centralization and key compromise risk.", Recommendation: "Use multisig wallet or Governance contract."},
		{ID: "SOL-006", Title: "Reentrancy (Classic + Cross-function)", Regex: `\.call\s*\{[^}]*value`, Severity: domain.SeverityCritical, Description: "External call before state update may allow reentrancy. Manual review required.", Recommendation: "Apply Checks-Effects-Interactions pattern and add ReentrancyGuard."},
		{ID: "SOL-007", Title: "Unchecked Low-level Call", Regex: `\.call\s*\{`, Severity: domain.SeverityHigh, Description: "Low-level call without checking return value may fail silently.", Recommendation: "Wrap in require(success, \"call failed\") or use Address library."},
		{ID: "SOL-008", Title: "Delegatecall to Untrusted Address", Regex: `delegatecall\s*\(`, Severity: domain.SeverityCritical, Description: "delegatecall to dynamic address may corrupt storage or inject code.", Recommendation: "Restrict delegatecall to trusted/proxied contracts only."},
		{ID: "SOL-009", Title: "ERC777 / Callback Reentrancy Hook", Regex: `tokensToSend|tokensReceived`, Severity: domain.SeverityHigh, Description: "ERC777 hooks can be exploited for reentrancy before balance updates.", Recommendation: "Add ReentrancyGuard and ensure state updated before external calls."},
		{ID: "SOL-010", Title: "Integer Overflow/Underflow (pre-0.8)", Regex: `pragma solidity\s*[\^~]?\s*0\.[5-7]`, Severity: domain.SeverityHigh, Description: "Solidity version <0.8 without SafeMath may overflow.", Recommendation: "Upgrade to Solidity >=0.8.x or use OpenZeppelin SafeMath."},
		{ID: "SOL-011", Title: "Division Before Multiplication", Regex: `\w+\s*\/\s*\w+\s*\*`, Severity: domain.SeverityHigh, Description: "Division before multiplication causes precision loss in financial calculations.", Recommendation: "Multiply first, then divide."},
		{ID: "SOL-012", Title: "Precision Loss in Fixed-Point Math", Regex: `\b(?:int|uint)\d+\s*\/\s*\d+\s*\*\s*\d+`, Severity: domain.SeverityMedium, Description: "Fixed-point arithmetic without proper scaling loses precision.", Recommendation: "Use libraries like ABDKMath64x64 or PRBMath."},
		{ID: "SOL-013", Title: "Storage Collision / Layout Mismatch in Proxy", Regex: `contract\s+\w+\s+is\s+\w*[Pp]roxy`, Severity: domain.SeverityCritical, Description: "Proxy pattern detected; ensure storage layout compatibility to avoid collisions.", Recommendation: "Follow OpenZeppelin unstructured storage pattern and test thoroughly."},
		{ID: "SOL-014", Title: "Missing Storage Gap in Upgradeable Contract", Regex: `contract\s+\w+\s+is\s+(?:Initializable|UUPS)`, Severity: domain.SeverityHigh, Description: "Upgradeable contract without storage gap may cause layout collision.", Recommendation: "Add __gap uint256[50] private at end of contract."},
		{ID: "SOL-015", Title: "Missing Beacon / Governance Safety in Upgrade", Regex: `upgradeTo\s*\(`, Severity: domain.SeverityCritical, Description: "Unrestricted upgradeTo allows malicious implementation change.", Recommendation: "Add Governance timelock and multisig for upgrade."},
		{ID: "SOL-016", Title: "Flash Loan Attack Vector (Price Dependency)", Regex: `getPrice|getAmount|swap\s*\(`, Severity: domain.SeverityHigh, Description: "Protocol relies on spot price from DEX, vulnerable to flash loan manipulation.", Recommendation: "Use TWAP or Chainlink oracle. Avoid direct DEX price queries."},
		{ID: "SOL-017", Title: "Oracle Manipulation (No TWAP / Single Source)", Regex: `latestAnswer\s*\(\s*\)|latestRoundData\s*\(\s*\)`, Severity: domain.SeverityCritical, Description: "Oracle price feed may be stale or manipulated without checks.", Recommendation: "Add staleness check, use multiple oracles, and implement TWAP."},
		{ID: "SOL-018", Title: "Insufficient Slippage / Deadline Protection", Regex: `function\s+swap\s*\([^)]*\)`, Severity: domain.SeverityHigh, Description: "Swap without minAmountOut and deadline allows sandwich/frontrun attacks.", Recommendation: "Add minAmountOut parameter and deadline check."},
		{ID: "SOL-019", Title: "Sandwich / Front-running (Predictable Hash)", Regex: `commit\s*\(|reveal\s*\(`, Severity: domain.SeverityMedium, Description: "Lack of commit-reveal scheme may allow front-running.", Recommendation: "Use commit-reveal pattern or Submarine Sends."},
		{ID: "SOL-020", Title: "Missing Input Validation (Zero Address)", Regex: `function\s+\w+\s*\([^)]*\)\s*(?:public|external)`, Severity: domain.SeverityMedium, Description: "Function lacks zero-address check on critical parameters.", Recommendation: "Add require(addr != address(0), \"zero address\")."},
		{ID: "SOL-021", Title: "Assert instead of Require", Regex: `assert\s*\(`, Severity: domain.SeverityLow, Description: "assert() consumes all gas; use require() for input validation.", Recommendation: "Replace assert with require for input/state validation."},
		{ID: "SOL-022", Title: "Unchecked Return Value from External Contract", Regex: `\.transfer\s*\(|\.send\s*\(`, Severity: domain.SeverityMedium, Description: "transfer/send may fail silently or revert unexpectedly.", Recommendation: "Use call{value: amount}(\"\") and check success."},
		{ID: "SOL-023", Title: "Signature Replay (Missing nonce / domain)", Regex: `ecrecover\s*\(`, Severity: domain.SeverityHigh, Description: "ecrecover without domain separator and nonce allows replay across contracts.", Recommendation: "Implement EIP-712 typed signatures with nonce and contract address."},
		{ID: "SOL-024", Title: "Weak Randomness (block.timestamp / block.number)", Regex: `block\.timestamp|block\.number|blockhash`, Severity: domain.SeverityHigh, Description: "Predictable randomness using block attributes can be manipulated by miners.", Recommendation: "Use Chainlink VRF for secure randomness."},
		{ID: "SOL-025", Title: "Unbounded Loops / Gas Griefing", Regex: `for\s*\([^)]*\)\s*\{`, Severity: domain.SeverityHigh, Description: "Unbounded loops can exceed block gas limit and cause DoS.", Recommendation: "Limit array size or use pull-over-push payment pattern."},
		{ID: "SOL-026", Title: "DoS with Block Gas Limit / State Bloat", Regex: `mapping\s*\([^)]*\)\s*(?:public|private|internal)\s+\w+\s*;`, Severity: domain.SeverityMedium, Description: "Unbounded data structures may lead to gas exhaustion.", Recommendation: "Implement batch processing and storage rent mechanisms."},
		{ID: "SOL-027", Title: "Hardcoded Credentials / Secrets", Regex: `"(?:secret|password|private_key|mnemonic|api_key)"`, Severity: domain.SeverityCritical, Description: "Hardcoded sensitive data is publicly visible on blockchain.", Recommendation: "Use environment variables or off-chain secret managers."},
		{ID: "SOL-028", Title: "Outdated Compiler / Floating Pragma", Regex: `pragma solidity\s*[\^~]?\s*(?:0\.[5-7]|0\.8\.[0-1][0-9])\s*;`, Severity: domain.SeverityLow, Description: "Outdated compiler version may contain known bugs.", Recommendation: "Use latest stable Solidity version with locked pragma."},
		{ID: "SOL-029", Title: "Missing Events on State Changes", Regex: `function\s+\w+\s*\([^)]*\)\s*(?:public|external)`, Severity: domain.SeverityInfo, Description: "Critical state changes should emit events for off-chain monitoring.", Recommendation: "Emit events on all state-changing functions."},
		{ID: "SOL-030", Title: "Use of Deprecated blockhash", Regex: `block\.blockhash\s*\(`, Severity: domain.SeverityLow, Description: "block.blockhash() is deprecated in newer Solidity versions.", Recommendation: "Use blockhash() global function instead."},
		{ID: "SOL-031", Title: "Shadowing Variables / Inheritance Issues", Regex: `contract\s+\w+\s+is\s+\w+\s*\{`, Severity: domain.SeverityMedium, Description: "Variable shadowing in inheritance may cause unintended behavior.", Recommendation: "Use unique variable names and check inheritance chains."},
		{ID: "SOL-032", Title: "Excessive Public State Variables", Regex: `(?:uint|int|bool|address|bytes)\s+(?:public)\s+\w+\s*;`, Severity: domain.SeverityInfo, Description: "Public state variables expose internal data unnecessarily.", Recommendation: "Use private/internal with explicit getter functions."},
		{ID: "SOL-033", Title: "Fake Token / Interface Spoofing", Regex: `interface\s+I\w+\s*\{`, Severity: domain.SeverityHigh, Description: "Untrusted token contracts may implement interfaces maliciously.", Recommendation: "Validate token contract code or use registry of verified tokens."},
		{ID: "SOL-034", Title: "Cross-Chain Bridge Logic Flaw", Regex: `burn\s*\([^)]*\)\s*.*mint\s*\(`, Severity: domain.SeverityCritical, Description: "Bridge burn-mint flow may have race conditions or double-spend.", Recommendation: "Implement atomic cross-chain operations with Merkle proofs."},
		{ID: "SOL-035", Title: "Governance Takeover (Vote Manipulation)", Regex: `function\s+vote\s*\(|delegate\s*\(`, Severity: domain.SeverityCritical, Description: "Voting mechanism without flash loan protection may be manipulated.", Recommendation: "Add voting delay and snapshot-based voting power."},
		{ID: "SOL-036", Title: "MEV-Specific (Tx Ordering Dependency)", Regex: `block\.coinbase|block\.gaslimit`, Severity: domain.SeverityMedium, Description: "Transaction ordering dependency allows MEV extraction.", Recommendation: "Design contracts to be MEV-resistant with fair ordering."},
		{ID: "SOL-037", Title: "Invariant Violations (totalSupply mismatch)", Regex: `mint\s*\([^)]*\)|burn\s*\([^)]*\)`, Severity: domain.SeverityHigh, Description: "Mint/burn may not maintain totalSupply invariant.", Recommendation: "Add invariant checks after mint/burn operations."},
		{ID: "SOL-038", Title: "Signature Malleability (ecrecover)", Regex: `ecrecover\s*\([^)]*\)`, Severity: domain.SeverityHigh, Description: "ecrecover is vulnerable to signature malleability (EIP-2).", Recommendation: "Use OpenZeppelin ECDSA library with EIP-2 protection."},
		{ID: "SOL-039", Title: "Timestamp Dependency for Critical Logic", Regex: `block\.timestamp\s*[><=]{1,2}`, Severity: domain.SeverityMedium, Description: "Timestamp dependence allows miner manipulation within ~900 seconds.", Recommendation: "Use block.number for duration measurements, never for entropy."},
		{ID: "SOL-040", Title: "Exposed Internal Functions / Visibility Issues", Regex: `function\s+_\w+\s*\([^)]*\)\s*(?:public|external)`, Severity: domain.SeverityLow, Description: "Internal function prefixed with _ is marked public/external.", Recommendation: "Change visibility to internal/private."},
	}
}
